mapper.select:
select b.user_id, p.person_profile_id
  from profile_person p
  join profile_person_binding b on b.person_profile_id = p.person_profile_id
 where b.user_id = #{userId}
   and p.person_profile_id = #{personProfileId}
   and p.full_name = #{fullName}
   and upper(right(trim(p.document_number), 4)) = #{documentLastFour}
   and p.status = 'ACTIVE'
   and p.del_flag = '0'
   and b.status = 'ACTIVE'
   and b.del_flag = '0'
 for update
